using System.ComponentModel.DataAnnotations;

namespace RecipeSharing.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(200)]
    public string Title { get; set; } = string.Empty;

    [Required]
    public string Category { get; set; } = string.Empty;

    [Required]
    public string Ingredients { get; set; } = string.Empty;

    [Required]
    public string Steps { get; set; } = string.Empty;

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeSharing.Models;

namespace RecipeSharing.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Basil, Olive oil", Steps = "1. Preheat oven to 475°F\n2. Roll out dough\n3. Spread crushed tomatoes\n4. Add torn mozzarella\n5. Bake 10-12 minutes\n6. Top with fresh basil", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook pasta al dente\n2. Crisp guanciale in pan\n3. Whisk eggs with cheese\n4. Toss hot pasta with guanciale\n5. Remove from heat, add egg mixture\n6. Toss until creamy", AverageRating = 4.8, RatingCount = 20 },
            new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Ginger, Garlic", Steps = "1. Marinate chicken in spiced yogurt\n2. Grill or broil chicken\n3. Sauté onions, ginger, garlic\n4. Add spices and tomato sauce\n5. Simmer, add cream\n6. Add chicken pieces, serve with rice", AverageRating = 4.6, RatingCount = 15 },
            new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian", Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Lime, Tamarind paste, Fish sauce", Steps = "1. Soak rice noodles\n2. Press and cube tofu, pan-fry\n3. Make sauce (tamarind, fish sauce, sugar)\n4. Stir-fry vegetables\n5. Add noodles and sauce\n6. Top with peanuts and lime", AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheese, Sour cream, Cumin, Chili powder", Steps = "1. Brown beef with spices\n2. Warm taco shells\n3. Dice tomatoes and shred lettuce\n4. Assemble tacos with beef\n5. Top with cheese, lettuce, tomato\n6. Add sour cream", AverageRating = 4.3, RatingCount = 18 },
            new() { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Cilantro, Red onion, Jalapeño, Salt", Steps = "1. Halve and pit avocados\n2. Mash to desired consistency\n3. Dice onion and jalapeño\n4. Chop cilantro\n5. Mix all ingredients\n6. Season with salt and lime", AverageRating = 4.7, RatingCount = 25 },
            new() { Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "Butter, Sugar, Brown sugar, Eggs, Vanilla, Flour, Baking soda, Chocolate chips", Steps = "1. Cream butter and sugars\n2. Beat in eggs and vanilla\n3. Mix flour, baking soda, salt\n4. Combine wet and dry ingredients\n5. Fold in chocolate chips\n6. Bake at 375°F for 9-11 minutes", AverageRating = 4.9, RatingCount = 30 },
            new() { Id = 8, Title = "Miso Soup", Category = "Asian", Ingredients = "Dashi stock, White miso paste, Tofu, Wakame seaweed, Green onions", Steps = "1. Heat dashi stock\n2. Dissolve miso paste in small amount of stock\n3. Cube tofu\n4. Rehydrate wakame\n5. Add tofu and wakame to pot\n6. Stir in miso (don't boil)\n7. Garnish with green onions", AverageRating = 4.1, RatingCount = 6 },
        };
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}

