﻿@page "/"
@inject RecipeSharing.Services.RecipeService RecipeService

<PageTitle>Recipe Sharing Community</PageTitle>

<h1>🍳 Recipe Sharing Community</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2>Browse by Category</h2>
<div class="row">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                    <p class="card-text">@RecipeService.GetByCategory(category).Count recipe(s)</p>
                    <a href="recipes/@category" class="btn btn-primary">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Asian" => "🥢",
        "Mexican" => "🌮",
        "Desserts" => "🍪",
        _ => "🍽️"
    };
}

arguments.file_text:
@page "/recipes"
@page "/recipes/{Category}"
@inject RecipeSharing.Services.RecipeService RecipeService

<PageTitle>@(Category ?? "All Recipes") - Recipe Sharing</PageTitle>

<h1>@(Category is not null ? $"📖 {Category} Recipes" : "📖 All Recipes")</h1>

@if (Category is not null)
{
    <p><a href="recipes">← Back to all categories</a></p>
}

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">@recipe.Category</p>
                        <p class="card-text">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string? Category { get; set; }

    private IReadOnlyList<RecipeSharing.Models.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        if (Category is not null)
        {
            recipes = RecipeService.GetByCategory(Category);
        }
        else
        {
            var all = new List<RecipeSharing.Models.Recipe>();
            foreach (var cat in RecipeService.GetCategories())
            {
                all.AddRange(RecipeService.GetByCategory(cat));
            }
            recipes = all;
        }
    }
}

@page "/recipe/{Id:int}"
@inject RecipeSharing.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - Recipe Sharing</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="recipes">← Browse recipes</a>
}
else
{
    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: @recipe.Category</p>

    <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.RatingCount" />

    <h3>🥘 Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>📝 Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.TrimStart();
            if (text.Length > 2 && text[1] == '.' && char.IsDigit(text[0]))
                text = text[2..].TrimStart();
            else if (text.Length > 3 && text[2] == '.' && char.IsDigit(text[0]) && char.IsDigit(text[1]))
                text = text[3..].TrimStart();
            <li>@text</li>
        }
    </ol>

    <a href="recipes/@recipe.Category" class="btn btn-outline-secondary mt-3">← Back to @recipe.Category</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeSharing.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeSharing.Services.RecipeService RecipeService

<div class="my-3 p-3 border rounded">
    <h4>Rate this Recipe</h4>
    <div class="star-rating" role="group" aria-label="Star rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link fs-3 p-0 me-1 @(star <= (hoverStar ?? selectedStar) ? "text-warning" : "text-secondary")"
                    @onclick="() => SubmitRating(star)"
                    @onmouseover="() => hoverStar = star"
                    @onmouseout="() => hoverStar = null"
                    aria-label="@star stars">
                @(star <= (hoverStar ?? selectedStar) ? "★" : "☆")
            </button>
        }
    </div>

    @if (submitted)
    {
        <p class="text-success mt-2">Thanks for rating!</p>
    }

    <p class="text-muted mt-2">
        ⭐ @CurrentRating.ToString("F1") average (@RatingCount ratings)
    </p>
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    [Parameter]
    public double CurrentRating { get; set; }

    [Parameter]
    public int RatingCount { get; set; }

    private int? hoverStar;
    private int selectedStar;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        submitted = true;
    }
}

