{"path": "/tmp/sv-a1d9dd4c0d3745f5823defe83e23b1a5/RecipeSharing/Components/Pages/StarRating.razor", "file_text": "@rendermode InteractiveServer
@inject RecipeSharing.Services.RecipeService RecipeService

<div class="my-3 p-3 border rounded">
    <h4>Rate this Recipe</h4>
    <div class="star-rating" role="group" aria-label="Star rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link fs-3 p-0 me-1 @(star <= (hoverStar ?? selectedStar) ? "text-warning" : "text-secondary")"
                    @onclick="() => SubmitRating(star)"
                    @onmouseover="() => hoverStar = star"
                    @onmouseout="() => hoverStar = null"
                    aria-label="@star stars">
                @(star <= (hoverStar ?? selectedStar) ? "★" : "☆")
            </button>
        }
    </div>

    @if (submitted)
    {
        <p class="text-success mt-2">Thanks for rating!</p>
    }

    <p class="text-muted mt-2">
        ⭐ @CurrentRating.ToString("F1") average (@RatingCount ratings)
    </p>
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    [Parameter]
    public double CurrentRating { get; set; }

    [Parameter]
    public int RatingCount { get; set; }

    private int? hoverStar;
    private int selectedStar;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        submitted = true;
    }
}
"}

